import { getGlobalSettings } from "@/db/models/GlobalSettings";
import { getHoldings } from "@/db/positionLedger";
import { markHoldings } from "@/db/pumpFunApi";

/** Plain-object trader with `muted` resolved against the global default when not explicitly set. */
export async function resolveTraderView(traderDoc, globalSettings) {
  const settings = globalSettings || (await getGlobalSettings());
  const plain = JSON.parse(JSON.stringify(traderDoc));
  return {
    ...plain,
    id: plain._id,
    mutedOverride: plain.muted,
    muted: plain.muted === null || plain.muted === undefined ? settings.defaultMuted : plain.muted,
  };
}

export async function resolveTraderViews(traderDocs) {
  const settings = await getGlobalSettings();
  return Promise.all(traderDocs.map((t) => resolveTraderView(t, settings)));
}

/** Trader view plus current mark-to-market holdings (live pump.fun price lookup - only call this for single-trader detail views, not list views). */
export async function resolveTraderViewWithHoldings(traderDoc) {
  const [view, holdings] = await Promise.all([resolveTraderView(traderDoc), getHoldings(traderDoc.address)]);
  const markedHoldings = await markHoldings(holdings);
  const holdingsValueUsd = markedHoldings.reduce((sum, h) => sum + (h.currentValueUsd || 0), 0);
  return { ...view, holdings: markedHoldings, holdingsValueUsd };
}
